//! Cross-language fixtures generated by linking the unchanged C# policy sources.
//! The generator, source SHA-256 values and scope are retained with the fixture.
use jiks_core::thermal::*;
use serde::Deserialize;
use std::collections::BTreeMap;

#[derive(Deserialize)]
struct Fixture {
    schema: u32,
    generator: String,
    source_sha256: BTreeMap<String, String>,
    synthetic_only: bool,
    hardware_calls: bool,
    application_performance_benchmark: bool,
    baseline: PowerEnvelope,
    capability: PowerCapability,
    policy_cases: Vec<PolicyCase>,
    grid_cases: Vec<GridCase>,
    arbiter_cases: Vec<ArbiterCase>,
}
#[derive(Deserialize)]
struct PolicyCase {
    id: String,
    source: String,
    options: ThermalOptions,
    steps: Vec<PolicyRow>,
}
#[derive(Deserialize)]
struct Reading {
    celsius: Option<f64>,
    sampled_at_ms: u64,
}
impl Reading {
    fn sample(&self) -> TemperatureReading {
        TemperatureReading {
            celsius: self.celsius.unwrap_or(f64::NAN),
            sampled_at_ms: self.sampled_at_ms,
        }
    }
}
#[derive(Deserialize)]
struct PolicyRow {
    now: u64,
    package: Reading,
    core: Reading,
    expected: ThermalDecision,
    fraction_scaled_target: PowerEnvelope,
    expires_at_ms: u64,
}
#[derive(Deserialize)]
struct GridCase {
    id: String,
    capability: PowerCapability,
    ceiling: PowerEnvelope,
    expected: Option<PowerEnvelope>,
}
#[derive(Deserialize)]
struct ArbiterCase {
    id: String,
    now: u64,
    policy: u64,
    mode: u64,
    expires_at_ms: u64,
    constraints: Vec<PowerConstraint>,
    expected: Option<PowerCommand>,
}
fn fixture() -> Fixture {
    serde_json::from_str(include_str!("fixtures/thermal-csharp.json")).unwrap()
}

#[test]
fn fixture_records_original_source_provenance_and_synthetic_scope() {
    let fixture = fixture();
    assert_eq!(fixture.schema, 1);
    assert!(
        fixture
            .generator
            .contains("four original C# pure sources linked unchanged")
    );
    assert!(fixture.synthetic_only);
    assert!(!fixture.hardware_calls);
    assert!(!fixture.application_performance_benchmark);
    assert_eq!(fixture.baseline, PowerEnvelope::new(70., 125.));
    assert_eq!(fixture.capability, PowerCapability::Y7000P);
    assert_eq!(fixture.source_sha256.len(), 4);
    for source in [
        "ThermalPolicy.cs",
        "PowerConstraintArbiter.cs",
        "HardwareCommandExecutor.cs",
        "ThermalControlSupervisor.cs",
    ] {
        let hash = &fixture.source_sha256[source];
        assert_eq!(hash.len(), 64);
        assert!(hash.bytes().all(|b| b.is_ascii_hexdigit()));
    }
    assert_eq!(fixture.policy_cases.len(), 4);
    assert_eq!(fixture.grid_cases.len(), 96);
    assert_eq!(fixture.arbiter_cases.len(), 7);
}

#[test]
fn policy_trajectories_match_original_csharp_decisions_and_scaled_targets() {
    let fixture = fixture();
    let mut checked = 0;
    for case in fixture.policy_cases {
        let policy = ThermalPolicy::new(case.options).unwrap();
        let mut previous = None;
        for (index, row) in case.steps.iter().enumerate() {
            let actual = match case.source.as_str() {
                "firmware" => {
                    policy.evaluate_firmware(row.package.sample(), row.now, previous.as_ref())
                }
                "package_core" => policy.evaluate(
                    row.package.sample(),
                    row.core.sample(),
                    row.now,
                    previous.as_ref(),
                ),
                other => panic!("unknown fixture source {other}"),
            };
            assert_eq!(actual, row.expected, "{} row {index}", case.id);
            let ceiling = PowerEnvelope::new(
                (fixture.baseline.long_watts * actual.power_fraction)
                    .max(fixture.capability.min_long),
                (fixture.baseline.short_watts * actual.power_fraction)
                    .max(fixture.capability.min_short),
            );
            let epoch = Epoch { policy: 3, mode: 7 };
            let command = resolve_power(
                fixture.baseline,
                &[PowerConstraint {
                    target: ceiling,
                    epoch,
                    expires_at_ms: row.now + 1500,
                }],
                fixture.capability,
                row.now,
                epoch,
                row.now + 2000,
            )
            .unwrap();
            assert_eq!(
                command.target, row.fraction_scaled_target,
                "{} row {index} scaled baseline",
                case.id
            );
            assert_eq!(command.expires_at_ms, row.expires_at_ms);
            previous = Some(actual);
            checked += 1;
        }
    }
    assert_eq!(checked, 36);
}

#[test]
fn decimal_and_machine_grids_match_original_csharp_results_without_overshoot() {
    for (index, case) in fixture().grid_cases.into_iter().enumerate() {
        let actual = case.capability.round_down(case.ceiling).ok();
        assert_eq!(
            actual, case.expected,
            "{} row {index} {:?}",
            case.id, case.ceiling
        );
        if let Some(actual) = actual {
            assert!(
                actual.long_watts <= case.ceiling.long_watts
                    && actual.short_watts <= case.ceiling.short_watts
            );
            assert!(actual.long_watts <= actual.short_watts);
        }
    }
}

#[test]
fn arbiter_deadlines_epochs_and_rejected_ceilings_match_original_csharp() {
    let fixture = fixture();
    for case in fixture.arbiter_cases {
        let actual = resolve_power(
            fixture.baseline,
            &case.constraints,
            fixture.capability,
            case.now,
            Epoch {
                policy: case.policy,
                mode: case.mode,
            },
            case.expires_at_ms,
        )
        .ok();
        assert_eq!(actual, case.expected, "{}", case.id);
    }
}
